```csharp
using System;

class NumberToWordsConverter
{
    private static string[] ones = {
        "zero", "one", "two", "three", "four", "five", "six", "seven", "eight", "nine", "ten",
        "eleven", "twelve", "thirteen", "fourteen", "fifteen", "sixteen", "seventeen", "eighteen", "nineteen"
    };

    private static string[] tens = {
        "", "", "twenty", "thirty", "forty", "fifty", "sixty", "seventy", "eighty", "ninety"
    };

    private static string[] thousands = {
        "", "thousand", "million", "billion", "trillion"
    };

    public static string ConvertNumberToWords(long number)
    {
        if (number == 0)
        {
            return ones[0];
        }

        if (number < 0)
        {
            return "minus " + ConvertNumberToWords(Math.Abs(number));
        }

        string words = "";

        int index = 0;

        while (number > 0)
        {
            if (number % 1000 != 0)
            {
                string partialNumberWords = ConvertNumberToWordsLessThanThousand((int)(number % 1000));
                words = partialNumberWords + thousands[index] + " " + words;
            }
            number /= 1000;
            index++;
        }

        return words.Trim();
    }

    private static string ConvertNumberToWordsLessThanThousand(int number)
    {
        string words = "";

        if (number % 100 < 20)
        {
            words = ones[number % 100];
            number /= 100;
        }
        else
        {
            words = ones[number % 10];
            number /= 10;

            words = tens[number % 10] + " " + words;
            number /= 10;
        }

        if (number == 0)
        {
            return words;
        }

        return ones[number] + " hundred " + words;
    }

    static void Main(string[] args)
    {
        Console.Write("Enter a number: ");
        long number = long.Parse(Console.ReadLine());

        string words = ConvertNumberToWords(number);
        Console.WriteLine("Words representation: " + words);

        Console.ReadLine();
    }
}
```

This code uses arrays to store the words for each digit position (ones, tens, thousands), and a recursive approach to convert the number to words. It also handles negative numbers by appending "minus" to the words representation. Additionally, it can handle numbers beyond the range of an integer by using the `long` data type for the input.

