using System.Numerics;

class Program
{
    static void Main()
    {
        int n = 1000000; // Change n to the desired value

        BigInteger sum = 0;
        for (int i = 1; i <= n; i++)
        {
            BigInteger numerator = BigInteger.Pow(i, i);
            BigInteger denominator = BigInteger.Pow(i, i);
            BigInteger term = BigInteger.Divide(numerator, denominator);

            sum += term;
        }

        Console.WriteLine(sum);
    }
}
