```csharp
using System;

public class Program
{
    public static void Main()
    {
        string input = "Hello, World!";
        int index = 5;
        char character = 'X';

        string result = InsertCharacter(input, index, character);
        Console.WriteLine(result);
    }

    public static string InsertCharacter(string input, int index, char character)
    {
        // Check if index is out of bounds
        if (index < 0)
            index = 0;
        else if (index > input.Length)
            index = input.Length;

        // Get the ASCII value of the last character in the string
        int lastCharAscii = (int)input[input.Length - 1];

        // Perform XOR operation between the ASCII value of the character at the given index and the last character
        int xorResult = (int)input[index] ^ lastCharAscii;

        // Check if the XOR result is a prime number
        bool isPrime = IsPrime(xorResult);

        // Find the next prime index to insert the character
        int primeIndex = FindNextPrimeIndex(input, index);

        // Insert the character at the nearest valid index or the next prime index
        if (isPrime)
            input = input.Insert(primeIndex, character.ToString());
        else
            input = input.Insert(index, character.ToString());

        return input;
    }

    public static bool IsPrime(int number)
    {
        if (number <= 1)
            return false;

        for (int i = 2; i * i <= number; i++)
        {
            if (number % i == 0)
                return false;
        }

        return true;
    }

    public static int FindNextPrimeIndex(string input, int index)
    {
        int nextIndex = index + 1;

        while (!IsPrime(nextIndex))
            nextIndex++;

        return nextIndex;
    }
}
```

In this example, the main function calls the "InsertCharacter" function with a sample input string "Hello, World!", an index of 5, and the character 'X'. The result is printed to the console.

The "InsertCharacter" function first handles the out-of-bounds index by setting it to the nearest valid index. It then calculates the XOR result between the ASCII value of the character at the given index and the ASCII value of the last character in the string. Next, it checks if the XOR result is a prime number using the "IsPrime" function. If it's a prime number, it finds the next prime index using the "FindNextPrimeIndex" function. Finally, it inserts the character at the nearest valid index or the next prime index and returns the modified string.

The "IsPrime" function checks if a number is prime by iterating from 2 to the square root of the number and checking for any divisors.

The "FindNextPrimeIndex" function finds the next prime index by incrementing the index until it finds a prime number using the "IsPrime" function.

