Here is a PascalABC.NET class that outputs the twin prime numbers up to n, where n is a prime number itself:

```csharp
using System;
using System.Collections.Generic;

class TwinPrimes
{
    static void Main(string[] args)
    {
        Console.WriteLine("Enter a prime number:");
        int n = Convert.ToInt32(Console.ReadLine());

        List<int> primes = GeneratePrimes(n);
        List<int> twinPrimes = FindTwinPrimes(primes);

        Console.WriteLine("Twin prime numbers up to {0}:", n);
        foreach (int twinPrime in twinPrimes)
        {
            Console.WriteLine(twinPrime);
        }
    }

    static List<int> GeneratePrimes(int n)
    {
        List<int> primes = new List<int>();

        for (int i = 2; i <= n; i++)
        {
            if (IsPrime(i))
            {
                primes.Add(i);
            }
        }

        return primes;
    }

    static bool IsPrime(int number)
    {
        if (number < 2)
        {
            return false;
        }

        for (int i = 2; i <= Math.Sqrt(number); i++)
        {
            if (number % i == 0)
            {
                return false;
            }
        }

        return true;
    }

    static List<int> FindTwinPrimes(List<int> primes)
    {
        List<int> twinPrimes = new List<int>();

        for (int i = 0; i < primes.Count - 1; i++)
        {
            if (primes[i + 1] - primes[i] == 2)
            {
                twinPrimes.Add(primes[i]);
                twinPrimes.Add(primes[i + 1]);
            }
        }

        return twinPrimes;
    }
}
```

Here's how the code works:
1. The user is prompted to enter a prime number (n).
2. The `GeneratePrimes` method generates a list of prime numbers up to n using the `IsPrime` method.
3. The `IsPrime` method checks if a number is prime by iterating from 2 to the square root of the number and checking if any of these numbers divide the number evenly.
4. The `FindTwinPrimes` method takes the list of primes and finds pairs of twin prime numbers by checking if the difference between consecutive primes is 2.
5. The twin prime numbers are printed in ascending order.

