                return (sign == 1) ? int.MaxValue : int.MinValue;
            }

            // Update the result
            result = result * 10 + digit;
        }
        else
        {
            // Return 0 if any non-digit character is found
            return 0;
        }

        index++;
    }

    return result * sign;
}
```

