namespace MultiThreadedGUIApp
{
    public partial class MainForm : Form
    {
        private List<string> predefinedMessages = new List<string>()
        {
            "Welcome!", "Bonjour!", "¡Bienvenido!", "Willkommen!", "Benvenuto!"
        };

        private Dictionary<string, List<string>> customMessages = new Dictionary<string, List<string>>()
        {
            {"English", new List<string>()},
            {"French", new List<string>()},
            {"Spanish", new List<string>()},
            {"German", new List<string>()},
            {"Italian", new List<string>()}
        };

        private CancellationTokenSource cancellationTokenSource;

        public MainForm()
        {
            InitializeComponent();
        }

        private void MainForm_Load(object sender, EventArgs e)
        {
            LoadCustomMessages();
            GenerateRandomMessage();
        }

        private void LoadCustomMessages()
        {
            try
            {
                if (File.Exists("custom_messages.txt"))
                {
                    using (StreamReader sr = new StreamReader("custom_messages.txt"))
                    {
                        string line;
                        while ((line = sr.ReadLine()) != null)
                        {
                            string[] parts = line.Split(':');
                            if (parts.Length == 2 && customMessages.ContainsKey(parts[0].Trim()))
                            {
                                customMessages[parts[0].Trim()].Add(parts[1].Trim());
                            }
                        }
                    }
                }
            }
            catch (Exception ex)
            {
                MessageBox.Show("Error loading custom messages: " + ex.Message, "Error", MessageBoxButtons.OK, MessageBoxIcon.Error);
            }
        }

        private void SaveCustomMessages()
        {
            try
            {
                using (StreamWriter sw = new StreamWriter("custom_messages.txt"))
                {
                    foreach (var language in customMessages.Keys)
                    {
                        foreach (var message in customMessages[language])
                        {
                            sw.WriteLine(language + " : " + message);
                        }
                    }
                }
            }
            catch (Exception ex)
            {
                MessageBox.Show("Error saving custom messages: " + ex.Message, "Error", MessageBoxButtons.OK, MessageBoxIcon.Error);
            }
        }

        private void GenerateRandomMessage()
        {
            cancellationTokenSource?.Cancel();

            cancellationTokenSource = new CancellationTokenSource();

            Task.Run(() =>
            {
                try
                {
                    Random random = new Random();
                    while (!cancellationTokenSource.Token.IsCancellationRequested)
                    {
                        int index = random.Next(predefinedMessages.Count);
                        string message = predefinedMessages[index];

                        Invoke(new Action(() =>
                        {
                            messageLabel.Text = message;
                        }));

                        Thread.Sleep(1000);
                    }
                }
                catch (OperationCanceledException)
                {
                    // Ignore
                }
                catch (Exception ex)
                {
                    MessageBox.Show("Error generating random message: " + ex.Message, "Error", MessageBoxButtons.OK, MessageBoxIcon.Error);
                }
            }, cancellationTokenSource.Token);
        }

        private void languageComboBox_SelectedIndexChanged(object sender, EventArgs e)
        {
            string selectedLanguage = languageComboBox.SelectedItem.ToString();
            if (customMessages.ContainsKey(selectedLanguage))
            {
                customMessageTextBox.Lines = customMessages[selectedLanguage].ToArray();
            }
            else
            {
                customMessageTextBox.Clear();
            }
        }

        private void saveButton_Click(object sender, EventArgs e)
        {
            string selectedLanguage = languageComboBox.SelectedItem.ToString();
            if (customMessages.ContainsKey(selectedLanguage))
            {
                customMessages[selectedLanguage] = new List<string>(customMessageTextBox.Lines);
                SaveCustomMessages();
                MessageBox.Show("Custom messages saved successfully!", "Success", MessageBoxButtons.OK, MessageBoxIcon.Information);
            }
        }

        protected override void OnFormClosing(FormClosingEventArgs e)
        {
            cancellationTokenSource?.Cancel();
            SaveCustomMessages();
            base.OnFormClosing(e);
        }
    }
}
