Here is a PascalABC.NET program that sorts the given array of integers using the custom sorting algorithm:

```csharp
using System;

class Program
{
    static void Main()
    {
        int[] nums = { 8, 5, 1, 3, 9, 6, 10, 15, 12, 18, 7, 11 };

        CustomSort(nums);

        Console.WriteLine("Sorted array:");
        foreach (int num in nums)
        {
            Console.Write(num + " ");
        }
    }

    static void CustomSort(int[] nums)
    {
        for (int i = 0; i < nums.Length - 1; i++)
        {
            for (int j = 0; j < nums.Length - i - 1; j++)
            {
                if (Compare(nums[j], nums[j + 1]) > 0)
                {
                    Swap(nums, j, j + 1);
                }
            }
        }
    }

    static int Compare(int a, int b)
    {
        if (IsEven(a) && IsDivisibleByThree(a))
        {
            if (IsEven(b) && IsDivisibleByThree(b))
            {
                return a.CompareTo(b);
            }
            else
            {
                return -1;
            }
        }
        else if (IsEven(a) && !IsDivisibleByThree(a))
        {
            if (IsEven(b) && !IsDivisibleByThree(b))
            {
                return -a.CompareTo(b);
            }
            else
            {
                return 1;
            }
        }
        else if (IsOdd(a) && IsDivisibleByFive(a))
        {
            if (IsOdd(b) && IsDivisibleByFive(b))
            {
                return a.CompareTo(b);
            }
            else
            {
                return -1;
            }
        }
        else
        {
            if (IsOdd(b) && !IsDivisibleByFive(b))
            {
                return -a.CompareTo(b);
            }
            else
            {
                return 1;
            }
        }
    }

    static bool IsEven(int num)
    {
        return num % 2 == 0;
    }

    static bool IsOdd(int num)
    {
        return num % 2 != 0;
    }

    static bool IsDivisibleByThree(int num)
    {
        return num % 3 == 0;
    }

    static bool IsDivisibleByFive(int num)
    {
        return num % 5 == 0;
    }

    static void Swap(int[] nums, int i, int j)
    {
        int temp = nums[i];
        nums[i] = nums[j];
        nums[j] = temp;
    }
}
```

The program uses the bubble sort algorithm to sort the array based on the custom sorting rules defined in the `Compare` method. The `IsEven`, `IsOdd`, `IsDivisibleByThree`, and `IsDivisibleByFive` methods are used to check the conditions for each rule. The `Swap` method is used to swap elements in the array. The sorted array is then printed to the console.

