        {
            Console.WriteLine("Enter the time zone:");
            string timeZoneInput = Console.ReadLine();

            DateTime dateTime;
            try
            {
                dateTime = GetDateTimeInTimeZone(timeZoneInput);
            }
            catch (TimeZoneNotFoundException)
            {
                Console.WriteLine("Invalid time zone input.");
                return;
