            catch (TimeZoneNotFoundException)
            {
                try
                {
                    timeZone = TimeZoneInfo.GetSystemTimeZones()
                        .Find(tz => tz.StandardName.Equals(timeZoneInput, StringComparison.OrdinalIgnoreCase)
                                     || tz.DisplayName.Equals(timeZoneInput, StringComparison.OrdinalIgnoreCase));
                }
                catch (TimeZoneNotFoundException)
                {
                    throw;
                }
            }

            return TimeZoneInfo.ConvertTimeFromUtc(DateTime.UtcNow, timeZone);
        }

        static string FormatDateTime(DateTime dateTime)
        {
            string dayOfWeek = dateTime.ToString("dddd");
            string formattedDateTime = dateTime.ToString("dd/MM/yyyy hh:mm:ss tt");

            return $"{dayOfWeek}, {formattedDateTime}";
        }
