Here's a PascalABC.NET code snippet to create a binary search tree with string payload and print it out using a custom data structure:

```csharp
using System;

public class TreeNode
{
    public string Data;
    public TreeNode Left;
    public TreeNode Right;

    public TreeNode(string data)
    {
        Data = data;
        Left = null;
        Right = null;
    }
}

public class BinarySearchTree
{
    private TreeNode root;

    public BinarySearchTree()
    {
        root = null;
    }

    public void Insert(string data)
    {
        TreeNode newNode = new TreeNode(data);

        if (root == null)
        {
            root = newNode;
        }
        else
        {
            TreeNode current = root;
            TreeNode parent;

            while (true)
            {
                parent = current;

                if (String.Compare(data, current.Data) < 0)
                {
                    current = current.Left;

                    if (current == null)
                    {
                        parent.Left = newNode;
                        break;
                    }
                }
                else
                {
                    current = current.Right;

                    if (current == null)
                    {
                        parent.Right = newNode;
                        break;
                    }
                }
            }
        }
    }

    private void InOrderTraversal(TreeNode node)
    {
        if (node != null)
        {
            InOrderTraversal(node.Left);
            Console.Write(node.Data + " ");
            InOrderTraversal(node.Right);
        }
    }

    public void PrintInOrder()
    {
        InOrderTraversal(root);
        Console.WriteLine();
    }
}

public class Program
{
    public static void Main(string[] args)
    {
        BinarySearchTree bst = new BinarySearchTree();
        bst.Insert("E");
        bst.Insert("B");
        bst.Insert("G");
        bst.Insert("A");
        bst.Insert("D");
        bst.Insert("F");
        bst.Insert("H");
        bst.PrintInOrder();
    }
}
```

In this code, we have defined a `TreeNode` class to represent each node of the binary search tree. The `BinarySearchTree` class is responsible for creating the tree, inserting nodes, and printing the tree using the in-order traversal technique.

In the `Insert` method, we traverse the tree from the root node and compare the input data with the current node's data to determine if we should move to the left or right subtree. If the current node is null, we insert the new node at that position. Otherwise, we continue traversing until we find a suitable position.

The `PrintInOrder` method calls the `InOrderTraversal` method to print the tree in ascending order. The `InOrderTraversal` method recursively visits the left subtree, then prints the current node, and finally visits the right subtree.

In the `Main` method, we create an instance of the `BinarySearchTree` class and insert several string values. Finally, we call the `PrintInOrder` method to print the tree in ascending order.

