{
    static void Main()
    {
        int[] arr = { 1, 2, 3, 4, 5, 6, 7 };
        int target = 7;

        int count = FindPairs(arr, target);

        Console.WriteLine("There are " + count + " pairs whose sum is equal to the target number " + target + ":");

        int pairNumber = 1;
        foreach (var pair in FindPairsWithIndices(arr, target))
        {
            Console.WriteLine("- Pair " + pairNumber + ": " + pair.Item1 + " (index " + pair.Item2 + ") + " + pair.Item3 + " (index " + pair.Item4 + ")");
            pairNumber++;
        }
    }

    static int FindPairs(int[] arr, int target)
    {
        int count = 0;

        for (int i = 0; i < arr.Length; i++)
        {
            for (int j = i + 1; j < arr.Length; j++)
            {
                if (arr[i] + arr[j] == target)
                {
                    count++;
                }
            }
        }

        return count;
    }

    static Tuple<int, int, int, int>[] FindPairsWithIndices(int[] arr, int target)
    {
        Tuple<int, int, int, int>[] pairs = new Tuple<int, int, int, int>[FindPairs(arr, target)];
        int pairIndex = 0;

        for (int i = 0; i < arr.Length; i++)
        {
            for (int j = i + 1; j < arr.Length; j++)
            {
                if (arr[i] + arr[j] == target)
                {
                    pairs[pairIndex] = new Tuple<int, int, int, int>(arr[i], i, arr[j], j);
                    pairIndex++;
                }
            }
        }

        return pairs;
    }
}
