    static void Main(string[] args)
    {
        int[] arr = { 2, 4, 6, 8, 8, 8, 10 };
        int target = 8;

        Tuple<int, int> result = BinarySearchFirstLastOccurrence(arr, target);
        Console.WriteLine("First Occurrence Index: " + result.Item1);
        Console.WriteLine("Last Occurrence Index: " + result.Item2);
    }

    static Tuple<int, int> BinarySearchFirstLastOccurrence(int[] arr, int target)
    {
        int firstOccurrence = BinarySearchFirstOccurrence(arr, target, 0, arr.Length - 1);
        int lastOccurrence = BinarySearchLastOccurrence(arr, target, 0, arr.Length - 1);
        return new Tuple<int, int>(firstOccurrence, lastOccurrence);
    }

    static int BinarySearchFirstOccurrence(int[] arr, int target, int low, int high)
    {
        if (low > high)
            return -1;

        int mid = low + (high - low) / 2;

        if (arr[mid] == target && (mid == 0 || arr[mid - 1] < target))
            return mid;
        else if (arr[mid] >= target)
            return BinarySearchFirstOccurrence(arr, target, low, mid - 1);
        else
            return BinarySearchFirstOccurrence(arr, target, mid + 1, high);
    }

    static int BinarySearchLastOccurrence(int[] arr, int target, int low, int high)
    {
        if (low > high)
            return -1;

        int mid = low + (high - low) / 2;

        if (arr[mid] == target && (mid == arr.Length - 1 || arr[mid + 1] > target))
            return mid;
        else if (arr[mid] > target)
            return BinarySearchLastOccurrence(arr, target, low, mid - 1);
        else
            return BinarySearchLastOccurrence(arr, target, mid + 1, high);
    }
}
```

