            {
                doneEvents[i] = new ManualResetEvent(false);
                primeCheckers[i] = new PrimeChecker(number, i, doneEvents[i]);
                ThreadPool.QueueUserWorkItem(primeCheckers[i].CheckPrime, i);
            }

            // Wait for all threads to finish
            WaitHandle.WaitAll(doneEvents);

            // Check the result of each thread
            foreach (PrimeChecker primeChecker in primeCheckers)
            {
                if (primeChecker.IsPrime)
                    return true;
            }

            return false;
