            long nextPrime = number;
            while (!IsPrime(++nextPrime)) { }

            // Find the previous prime number smaller than the given number
            long prevPrime = number;
            while (!IsPrime(--prevPrime)) { }

            // Find the closest prime number by comparing the distances
            if (number - prevPrime < nextPrime - number)
                return prevPrime;
            else
                return nextPrime;
