```csharp
using System;

class Program
{
    static void Main()
    {
        // Read an array of strings from the user
        Console.WriteLine("Enter a list of strings (separated by spaces):");
        string input = Console.ReadLine();
        string[] strings = input.Split(' ');

        // Sort the array using bubble sort
        BubbleSort(strings);

        // Print the sorted array
        Console.WriteLine("\nSorted Array:");
        foreach (string str in strings)
        {
            Console.WriteLine(str);
        }
    }

    static void BubbleSort(string[] array)
    {
        int n = array.Length;
        for (int i = 0; i < n - 1; i++)
        {
            for (int j = 0; j < n - i - 1; j++)
            {
                if (CompareStrings(array[j], array[j + 1]) > 0)
                {
                    // Swap array[j] and array[j + 1]
                    string temp = array[j];
                    array[j] = array[j + 1];
                    array[j + 1] = temp;
                }
            }
        }
    }

    static int CompareStrings(string a, string b)
    {
        int minLength = Math.Min(a.Length, b.Length);

        for (int i = 0; i < minLength; i++)
        {
            if (a[i] != b[i])
            {
                // Compare characters case-insensitively
                int result = char.ToLower(a[i]).CompareTo(char.ToLower(b[i]));
                if (result != 0)
                {
                    return result;
                }
            }
        }

        // If all characters match up to the minimum length, the shorter string comes first
        return a.Length - b.Length;
    }
}
```

