        // Count the frequency of each letter in string1
        foreach (char c in string1)
        {
            if (frequency1.ContainsKey(c))
            {
                frequency1[c]++;
            }
            else
            {
                frequency1[c] = 1;
            }
        }

        // Count the frequency of each letter in string2
        foreach (char c in string2)
        {
            if (frequency2.ContainsKey(c))
            {
                frequency2[c]++;
            }
            else
