public static int Fibonacci(int n)
{
    // Base case: return 0 for Fibonacci(0)
    if (n == 0)
    {
        return 0;
    }
    // Base case: return 1 for Fibonacci(1) or Fibonacci(2)
    else if (n == 1 || n == 2)
    {
        return 1;
    }
    // Recursive case: Fibonacci(n) = Fibonacci(n-1) + Fibonacci(n-2)
    else
