using System;
using System.Collections.Generic;

public class MaximumDifferenceFinder
{
    public int MaximumDifference(List<int> numbers)
    {
        if (numbers == null || numbers.Count < 2)
        {
            return 0;
        }

        int minNumber = numbers[0];
        int maxDifference = 0;

        foreach (int number in numbers)
        {
            minNumber = Math.Min(minNumber, number);
            maxDifference = Math.Max(maxDifference, number - minNumber);
        }

        return maxDifference;
    }
}
