public class VariantManager
{
    private Dictionary<string, object> defaultValues = new Dictionary<string, object>();
    private Dictionary<string, object> variantValues = new Dictionary<string, object>();
    private Dictionary<string, Func<object, object>> legacyVariantFunctions = new Dictionary<string, Func<object, object>>();

    public void SetDefaultVariantValue(string settingName, object value)
    {
        defaultValues[settingName] = value;
    }

    public void SetVariantValue(string settingName, object value)
    {
        variantValues[settingName] = value;
    }

    public void SetLegacyVariantValue(string settingName, Func<object, object> legacyFunction)
    {
        legacyVariantFunctions[settingName] = legacyFunction;
    }

    public object GetDefaultVariantValue(string settingName)
    {
        return defaultValues.ContainsKey(settingName) ? defaultValues[settingName] : null;
    }

    public object GetVariantValue(string settingName)
    {
        return variantValues.ContainsKey(settingName) ? variantValues[settingName] : null;
    }

    public object GetCurrentValue(string settingName)
    {
        if (variantValues.ContainsKey(settingName))
        {
            return variantValues[settingName];
        }
        else if (legacyVariantFunctions.ContainsKey(settingName))
        {
            return legacyVariantFunctions[settingName](defaultValues[settingName]);
        }
        else
        {
            return defaultValues.ContainsKey(settingName) ? defaultValues[settingName] : null;
        }
    }
}
