using System;
using System.Collections.Generic;
using System.Linq;

public class HierarchyPath
{
    private readonly string[] elements;

    private HierarchyPath(string[] elements)
    {
        this.elements = elements;
    }

    public static HierarchyPath Create(string path)
    {
        if (string.IsNullOrEmpty(path))
        {
            throw new ArgumentException("Path cannot be null or empty.");
        }

        var elements = path.Split('/');
        return new HierarchyPath(elements);
    }
}

public class HierarchyDictionary<TValue>
{
    private readonly Dictionary<string, TValue> dictionary;

    public HierarchyDictionary()
    {
        dictionary = new Dictionary<string, TValue>();
    }

    public void Add(string key, TValue value)
    {
        if (string.IsNullOrEmpty(key))
        {
            throw new ArgumentException("Key cannot be null or empty.");
        }

        dictionary[key] = value;
    }

    public bool Remove(string key)
    {
        return dictionary.Remove(key);
    }

    public TValue GetValue(string key)
    {
        if (dictionary.TryGetValue(key, out TValue value))
        {
            return value;
        }
        throw new KeyNotFoundException($"Key '{key}' not found in the hierarchy dictionary.");
    }

    public IEnumerable<string> GetKeys(string prefix)
    {
        return dictionary.Keys.Where(k => k.StartsWith(prefix));
    }

    public IEnumerable<string> GetAllKeys()
    {
        return dictionary.Keys;
    }
}

public interface IHierarchyNode<TKey, TValue>
{
    TKey Key { get; }
    TValue Value { get; }
    IEnumerable<IHierarchyNode<TKey, TValue>> Children { get; }
}

public class HierarchyNode<TKey, TValue> : IHierarchyNode<TKey, TValue>
{
    public TKey Key { get; set; }
    public TValue Value { get; set; }
    public List<HierarchyNode<TKey, TValue>> Children { get; set; }
}
