        .AddMvc(options =>
        {
            options.InputFormatters.Insert(0, new NdjsonInputFormatter());
            options.OutputFormatters.Insert(0, new NdjsonOutputFormatter());
        })
        .SetCompatibilityVersion(CompatibilityVersion.Version_3_0);
}
```

Finally, to test the custom JSON formatter, you can create a test scenario using Xunit as follows:

```csharp
