    public class DataSerializer
    {
        public string Serialize(int data)
        {
            return data.ToString();
        }

        public string Serialize(string data)
        {
            return "\"" + data + "\"";
        }

        public string Serialize(bool data)
        {
            return data.ToString().ToLower();
        }

        public string Serialize(int[] data)
        {
            StringBuilder sb = new StringBuilder();
            sb.Append("[");
            for (int i = 0; i < data.Length; i++)
            {
                sb.Append(Serialize(data[i]));
                if (i < data.Length - 1)
                {
                    sb.Append(",");
                }
            }
            sb.Append("]");
            return sb.ToString();
        }

        public string Serialize(string[] data)
        {
            StringBuilder sb = new StringBuilder();
            sb.Append("[");
            for (int i = 0; i < data.Length; i++)
            {
                sb.Append(Serialize(data[i]));
                if (i < data.Length - 1)
                {
                    sb.Append(",");
                }
            }
            sb.Append("]");
            return sb.ToString();
        }
    }

    public class DataDeserializer
    {
        public int DeserializeInt(string data)
        {
            return int.Parse(data);
        }

        public string DeserializeString(string data)
        {
            return data.Trim('"');
        }

        public bool DeserializeBool(string data)
        {
            return bool.Parse(data);
        }

        public int[] DeserializeIntArray(string data)
        {
            string[] elements = data.Trim('[', ']').Split(',');
            int[] result = new int[elements.Length];
            for (int i = 0; i < elements.Length; i++)
            {
                result[i] = DeserializeInt(elements[i]);
            }
            return result;
