    class CompileAsset : IAssetTransformer
    {
        public CompileAsset(ICompiler compiler, IDirectory rootDirectory)
        {
            this.compiler = compiler;
            this.rootDirectory = rootDirectory;
        }

        readonly ICompiler compiler;
        readonly IDirectory rootDirectory;

        public Func<Stream> Transform(Func<Stream> openSourceStream, IAsset asset)
        {
            return () =>
            {
                using (var sourceStream = openSourceStream())
                {
                    // Compile the source stream using the specified compiler
                    var compiledStream = new MemoryStream();
                    compiler.Compile(sourceStream, compiledStream, rootDirectory, asset);
                    compiledStream.Seek(0, SeekOrigin.Begin); // Reset the stream position
                    return compiledStream;
                }
            };
        }
    }
}
