using System;
using System.Security.Cryptography;
using System.Text;

public class DataEncryption
{
    public static byte[] Encrypt(byte[] data, string password, int passwordHashPasses)
    {
        if (data == null || data.Length == 0)
        {
            throw new ArgumentNullException(nameof(data), "Data cannot be null or empty.");
        }

        if (string.IsNullOrEmpty(password))
        {
            throw new ArgumentException("Password cannot be null or empty.", nameof(password));
        }

        if (passwordHashPasses <= 0)
        {
            throw new ArgumentException("Password hash passes should be a positive integer.", nameof(passwordHashPasses));
        }

        byte[] passwordBytes = Encoding.UTF8.GetBytes(password);
        using (var sha256 = SHA256.Create())
        {
            for (int i = 0; i < passwordHashPasses; i++)
            {
                passwordBytes = sha256.ComputeHash(passwordBytes);
            }
        }

        byte[] encryptedData;
        using (Aes aesAlg = Aes.Create())
        {
            aesAlg.Key = passwordBytes;
            aesAlg.IV = new byte[16]; // Initialization Vector

            ICryptoTransform encryptor = aesAlg.CreateEncryptor(aesAlg.Key, aesAlg.IV);

            using (var msEncrypt = new System.IO.MemoryStream())
            {
                using (var csEncrypt = new CryptoStream(msEncrypt, encryptor, CryptoStreamMode.Write))
                {
                    csEncrypt.Write(data, 0, data.Length);
                    csEncrypt.FlushFinalBlock();
                    encryptedData = msEncrypt.ToArray();
                }
            }
        }

        return encryptedData;
    }

    public static byte[] Decrypt(byte[] encryptedData, string password, int passwordHashPasses)
    {
        if (encryptedData == null || encryptedData.Length == 0)
        {
            throw new ArgumentNullException(nameof(encryptedData), "Encrypted data cannot be null or empty.");
        }

        if (string.IsNullOrEmpty(password))
        {
            throw new ArgumentException("Password cannot be null or empty.", nameof(password));
        }

        if (passwordHashPasses <= 0)
        {
            throw new ArgumentException("Password hash passes should be a positive integer.", nameof(passwordHashPasses));
        }

        byte[] passwordBytes = Encoding.UTF8.GetBytes(password);
        using (var sha256 = SHA256.Create())
        {
            for (int i = 0; i < passwordHashPasses; i++)
            {
                passwordBytes = sha256.ComputeHash(passwordBytes);
            }
        }

        byte[] decryptedData;
        using (Aes aesAlg = Aes.Create())
        {
            aesAlg.Key = passwordBytes;
            aesAlg.IV = new byte[16]; // Initialization Vector

            ICryptoTransform decryptor = aesAlg.CreateDecryptor(aesAlg.Key, aesAlg.IV);

            using (var msDecrypt = new System.IO.MemoryStream(encryptedData))
            {
                using (var csDecrypt = new CryptoStream(msDecrypt, decryptor, CryptoStreamMode.Read))
                {
                    using (var decryptedStream = new System.IO.MemoryStream())
                    {
                        csDecrypt.CopyTo(decryptedStream);
                        decryptedData = decryptedStream.ToArray();
                    }
                }
            }
        }

        return decryptedData;
    }

    public static void Main()
    {
        byte[] originalData = Encoding.UTF8.GetBytes("Sample data to be encrypted and decrypted.");
        string password = "StrongPassword";
        int passwordHashPasses = 10000;

        byte[] encryptedData = Encrypt(originalData, password, passwordHashPasses);
        byte[] decryptedData = Decrypt(encryptedData, password, passwordHashPasses);

        string originalText = Encoding.UTF8.GetString(originalData);
        string decryptedText = Encoding.UTF8.GetString(decryptedData);

        Console.WriteLine("Original Data: " + originalText);
        Console.WriteLine("Encrypted Data: " + Convert.ToBase64String(encryptedData));
        Console.WriteLine("Decrypted Data: " + decryptedText);
    }
}
```

This solution provides the implementation of the encryption and decryption methods based on the given specifications. It uses the SHA-256 hashing algorithm to hash the password and AES symmetric encryption algorithm for data encryption and decryption. The `Main` method demonstrates the usage of these methods by encrypting a sample data and then decrypting the encrypted data to obtain the original data.

