public static unsafe uint TranslateVirtualToPhysical(uint virtualAddress)
{
    // Calculate the index into the translation table using the most significant 12 bits of the virtual address.
    uint translationTableIndex = virtualAddress >> 20;

    // Set the translation table base register to the base address of the translation table.
    SetTranslationTableBaseRegister(&translationTable[0]);

    // Retrieve the entry from the translation table corresponding to the calculated index.
    uint translationTableEntry = translationTable[translationTableIndex];

    // Extract the physical page address from the translation table entry.
    uint physicalPageAddress = translationTableEntry & 0xFFFFF000;

    // Calculate the physical address by combining the physical page address and the offset within the 1MB section.
    uint physicalAddress = physicalPageAddress | (virtualAddress & 0x00000FFF);

    return physicalAddress;
}
