    private Dictionary<string, List<EventHandler<MessageEvent>>> eventHandlers = new Dictionary<string, List<EventHandler<MessageEvent>>>();

    public void Subscribe(string eventName, EventHandler<MessageEvent> eventHandler)
    {
        if (!eventHandlers.ContainsKey(eventName))
        {
            eventHandlers[eventName] = new List<EventHandler<MessageEvent>>();
        }
        eventHandlers[eventName].Add(eventHandler);
    }

    public void Unsubscribe(string eventName, EventHandler<MessageEvent> eventHandler)
    {
        if (eventHandlers.ContainsKey(eventName))
        {
            eventHandlers[eventName].Remove(eventHandler);
        }
