using UnityEngine;

public class PositionTransformer
{
    public float rotationX;
    public float rotationY;
    public float rotationZ;
    public Vector3 translationVector;
    public float scaleFactor;

    public Matrix4x4 Matrix
    {
        get
        {
            Matrix4x4 matrix = Matrix4x4.identity;

            // Translation
            matrix = Matrix4x4.Translate(translationVector) * matrix;

            // Rotation around x-axis
            matrix = Matrix4x4.Rotate(Quaternion.Euler(rotationX, 0, 0)) * matrix;

            // Rotation around y-axis
            matrix = Matrix4x4.Rotate(Quaternion.Euler(0, rotationY, 0)) * matrix;

            // Rotation around z-axis
            matrix = Matrix4x4.Rotate(Quaternion.Euler(0, 0, rotationZ)) * matrix;

            // Scaling
            matrix = Matrix4x4.Scale(new Vector3(scaleFactor, scaleFactor, scaleFactor)) * matrix;

            return matrix;
        }
    }
}
