using System;
using System.Data;
using System.Linq;
using System.Collections.Generic;

public class Program
{
    private static Random _r = new Random();

    public static Dictionary<string, int> CalculateColumnSums(DataTable table)
    {
        Dictionary<string, int> columnSums = new Dictionary<string, int>();

        for (int i = 0; i < table.Columns.Count; i++)
        {
            string columnName = table.Columns[i].ColumnName;
            int sum = 0;
            foreach (DataRow row in table.Rows)
            {
                sum += Convert.ToInt32(row[i]);
            }
            columnSums.Add(columnName, sum);
        }

        return columnSums;
    }

    public static void Main()
    {
        DataTable table = new DataTable();
        table.Columns.AddRange(Enumerable.Range(0, _r.Next(3, 10))
            .Select(c => new DataColumn($"Column {c + 1}", typeof(int))
            ).ToArray());

        for (int i = 0; i < 10; i++)
        {
            table.Rows.Add(Enumerable.Range(0, table.Columns.Count)
                .Select(c => (object)_r.Next(0, 100)).ToArray());
        }

        Dictionary<string, int> sums = CalculateColumnSums(table);
        foreach (var kvp in sums)
        {
            Console.WriteLine($"{kvp.Key}: {kvp.Value}");
        }
    }
}
