You are given a code snippet from a PascalABC.NET program. Your task is to write a program that can parse the given code snippet and extract the namespaces and class names from it.

Write a function or program that takes the code snippet as input and returns a list of namespaces and class names present in the code.

For example, given the input code snippet:
```
using Kujikatsu086.Extensions;
using Kujikatsu086.Numerics;
using Kujikatsu086.Questions;

namespace Kujikatsu086.Questions
{
    /// <summary>
    /// https://atcoder.jp/contests/nomura2020/tasks/nomura2020_a
    /// </summary>
    public class QuestionA : AtCoderQuestionBase
```
The expected output would be:
```
Namespaces: 
- Kujikatsu086.Extensions
- Kujikatsu086.Numerics
- Kujikatsu086.Questions

Class: 
- QuestionA
```

output:
```csharp
using System;
using System.Collections.Generic;
using System.Text.RegularExpressions;

public class CodeParser
{
    public static (List<string> namespaces, List<string> classes) ParseCode(string codeSnippet)
    {
        List<string> namespaces = new List<string>();
        List<string> classes = new List<string>();

        string[] lines = codeSnippet.Split('\n');

        foreach (string line in lines)
        {
            if (line.Trim().StartsWith("using"))
            {
                string namespaceName = Regex.Match(line, "using (.+?);").Groups[1].Value;
                namespaces.Add(namespaceName);
            }
            else if (line.Trim().StartsWith("public class"))
            {
                string className = Regex.Match(line, "public class (.+?) :").Groups[1].Value;
                classes.Add(className);
            }
        }

        return (namespaces, classes);
    }

    public static void Main()
    {
        string codeSnippet = @"
using Kujikatsu086.Extensions;
using Kujikatsu086.Numerics;
using Kujikatsu086.Questions;

namespace Kujikatsu086.Questions
{
    /// <summary>
    /// https://atcoder.jp/contests/nomura2020/tasks/nomura2020_a
    /// </summary>
    public class QuestionA : AtCoderQuestionBase
";
        var result = ParseCode(codeSnippet);
        Console.WriteLine("Namespaces:");
        foreach (var ns in result.namespaces)
        {
            Console.WriteLine("- " + ns);
        }
        Console.WriteLine("Class:");
        foreach (var cls in result.classes)
        {
            Console.WriteLine("- " + cls);
        }
    }
}
```

