// Calculate the camera position based on the target and field of view
void UpdateCameraPosition(Transform target, Camera cam, float viewWidth, float fov)
{
    Vector3 pos = target.position;

    // Calculate the distance based on the view width and field of view
    float distance = viewWidth / (2f * Mathf.Tan(0.5f * fov * Mathf.Deg2Rad));

    // Set the z position of the camera to the negative of the calculated distance
    pos.z = -Mathf.Abs(distance);

    // Set the camera's position to the calculated position
    cam.transform.position = pos;

    // Log the calculated distance for debugging purposes
    Debug.Log(distance);
}
