public class WhileLoop : IExecutable
{
    private readonly IExpressionExecutor _condition;
    private readonly IExecutable _body;

    public WhileLoop(IExpressionExecutor condition, IExecutable body)
    {
        _condition = condition;
        _body = body;
    }

    public Value? Execute(Frame frame, TextWriter output)
    {
        while (_condition.Execute(frame, output).AsBoolean)
        {
            var result = _body.Execute(frame, output);

            if (result.HasValue)
            {
                return result;
            }
        }

        return null;
    }
}
