    public class EventHandler
    {
        private Dictionary<string, List<Action>> eventHandlers;

        public EventHandler()
        {
            eventHandlers = new Dictionary<string, List<Action>>();
        }

        public void RegisterHandler(string eventName, Action handler)
        {
            if (!eventHandlers.ContainsKey(eventName))
            {
                eventHandlers[eventName] = new List<Action>();
            }
            eventHandlers[eventName].Add(handler);
        }

        public void UnregisterHandler(string eventName, Action handler)
        {
            if (eventHandlers.ContainsKey(eventName))
            {
                eventHandlers[eventName].Remove(handler);
            }
        }

        public void RaiseEvent(string eventName)
        {
            if (eventHandlers.ContainsKey(eventName))
            {
                foreach (var handler in eventHandlers[eventName])
                {
                    handler.Invoke();
                }
            }
        }
    }

    public class Program
    {
        public static void Main()
        {
            EventHandler eventHandler = new EventHandler();

            // Register event handlers
            eventHandler.RegisterHandler("OnBatchStart", () => Console.WriteLine("Batch processing started"));
            eventHandler.RegisterHandler("OnBatchComplete", () => Console.WriteLine("Batch processing completed"));

            // Trigger events
            eventHandler.RaiseEvent("OnBatchStart");
            eventHandler.RaiseEvent("OnBatchComplete");
        }
    }
}
