        static void Main(string[] args)
        {
            Console.WriteLine("Enter process name or keyword to filter:");
            string filter = Console.ReadLine();

            using (PowerShell PowerShellInstance = PowerShell.Create())
            {
                PowerShellInstance.AddScript("Get-Process | Where-Object { $_.ProcessName -like '*" + filter + "*' } | Select-Object ProcessName, Id");
                var processes = PowerShellInstance.Invoke();

                if (PowerShellInstance.HadErrors)
                {
                    foreach (var error in PowerShellInstance.Streams.Error)
                    {
                        Console.WriteLine("Error: " + error.ToString());
                    }
                }
                else
                {
                    foreach (dynamic process in processes)
                    {
                        Console.WriteLine($"Process Name: {process.ProcessName}, ID: {process.Id}");
                    }

                    Console.WriteLine("Enter process name or ID to terminate:");
                    string processToTerminate = Console.ReadLine();

                    PowerShellInstance.Commands.Clear();
                    PowerShellInstance.AddScript("Stop-Process -Name " + processToTerminate + " -Force");
                    PowerShellInstance.AddScript("Stop-Process -Id " + processToTerminate + " -Force");
                    PowerShellInstance.Invoke();
                }
            }
        }
    }
}
