// Define the base class for custom validation attributes
public abstract class ValidationAttribute : Attribute
{
    public abstract bool IsValid(object value);
}

// Define a specific validation attribute to check if a value is within a specified range
public class RangeAttribute : ValidationAttribute
{
    private readonly int _min;
    private readonly int _max;

    public RangeAttribute(int min, int max)
    {
        _min = min;
        _max = max;
    }

    public override bool IsValid(object value)
    {
        if (value is int intValue)
        {
            return intValue >= _min && intValue <= _max;
        }
        return false;
    }
}

// Define a specific validation attribute to check if a value is required (not null or empty)
public class RequiredAttribute : ValidationAttribute
{
    public override bool IsValid(object value)
    {
        if (value is string strValue)
        {
            return !string.IsNullOrEmpty(strValue);
        }
        return value != null;
    }
}

// Implement a Validator class to validate objects based on the applied validation attributes
public static class Validator
{
    public static bool Validate(object obj)
    {
        var properties = obj.GetType().GetProperties();
        foreach (var property in properties)
        {
            var validationAttributes = property.GetCustomAttributes(typeof(ValidationAttribute), true);
            foreach (var attribute in validationAttributes)
            {
                if (attribute is ValidationAttribute validationAttribute)
                {
                    var value = property.GetValue(obj);
                    if (!validationAttribute.IsValid(value))
                    {
                        return false;
                    }
                }
            }
        }
        return true;
    }
}

// Demonstrate the usage of custom validation attributes and the Validator class
public class User
{
    [Required]
    public string Name { get; set; }

    [Range(18, 100)]
    public int Age { get; set; }
}

public class Program
{
    public static void Main()
    {
        var validUser = new User { Name = "John Doe", Age = 25 };
        var invalidUser = new User { Name = "", Age = 16 };

        Console.WriteLine("Valid user: " + Validator.Validate(validUser)); // Output: Valid user: True
        Console.WriteLine("Invalid user: " + Validator.Validate(invalidUser)); // Output: Invalid user: False
    }
}
```

