public class RandomNumberProcessor
{
    public (int, double, float, int) ProcessRandomNumbers()
    {
        Random rnd = new Random((int)Stopwatch.GetTimestamp());
        int sumShort = 0;
        double sumInt = 0;
        float maxFloat = float.MinValue;
        int trueCount = 0;

        for (int i = 0; i < 100; i++)
        {
            short short_number = (short)rnd.Next(short.MinValue, short.MaxValue);
            ushort short_number_1 = (ushort)rnd.Next(ushort.MinValue, ushort.MaxValue);

            int int_number = rnd.Next(int.MinValue, int.MaxValue);
            uint int_number_1 = (uint)rnd.Next(0, int.MaxValue);

            float float_number = rnd.Next(-100000, 100000) / 100;

            var bool_value = short_number % 2 == 1;

            sumShort += short_number;
            sumInt += int_number;
            maxFloat = Math.Max(maxFloat, float_number);
            if (bool_value)
            {
                trueCount++;
            }
        }

        double averageInt = sumInt / 100;

        return (sumShort, averageInt, maxFloat, trueCount);
    }
}

